"""The cyclic group generated by a rational quarter turn.

Origin: code/python/src/qm/campaigns/rotation_groups.py
Claim: R = [[0, −1], [1, 0]] has order 4, found by multiplying until the identity.
AuthorityEffect: None.
"""
from fractions import Fraction


class RotationError(Exception):
    """The quarter turn did not have order 4."""


def _mul(left, right):
    return tuple(
        tuple(sum(left[i][k] * right[k][j] for k in range(2)) for j in range(2))
        for i in range(2)
    )


def quarter_turn_order() -> int:
    turn = ((Fraction(0), Fraction(-1)), (Fraction(1), Fraction(0)))
    current = ((Fraction(1), Fraction(0)), (Fraction(0), Fraction(1)))
    identity = current
    for exponent in range(1, 8):
        current = _mul(current, turn)
        if current == identity:
            if exponent != 4:
                raise RotationError(f"quarter turn order is {exponent}, not 4")
            return exponent
    raise RotationError("quarter turn did not return to the identity")
